pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 depositAmount, uint96 withdrawAmount, address actor) public {
        // Bound amounts to avoid overflow and keep wide domain
        vm.assume(actor != address(0) && actor != address(c));
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));
        withdrawAmount = uint96(bound(withdrawAmount, 1, type(uint96).max));

        // Deploy a helper that reverts on ETH receipt to trigger the bug path
        Reverter reverter = new Reverter();

        // Deposit from actor into reverter's credit slot
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Deposit from reverter (so reverter has credit and will trigger the failing transfer)
        vm.deal(address(reverter), withdrawAmount);
        vm.prank(address(reverter));
        c.deposit{value: withdrawAmount}();

        uint balanceBefore = address(c).balance;

        // reverter attempts to withdraw — its fallback reverts, causing the external call to fail
        vm.prank(address(reverter));
        c.withdrawAll();

        uint balanceAfter = address(c).balance;
        // In the reference, the revert propagates and balance remains unchanged.
        // In the buggy version, credit is zeroed and balance reduced without transferring ETH,
        // so balanceAfter < balanceBefore.
        assertTrue(balanceAfter == balanceBefore);
    }
}

