pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, uint96 extra, address recipient) public {
        // 1. Keep amounts positive but non-zero to ensure deposit and withdrawal
        vm.assume(amount > 0);
        vm.assume(extra >= 0);
        // 2. Deploy an adversarial recipient that reverts on receiving ETH
        Reverter reverter = new Reverter();
        // Fund and deposit using a plain EOA (we use address(this) for simplicity)
        vm.deal(address(this), uint256(amount) + uint256(extra));
        // Deposit to the reverter address
        c.deposit{value: amount}();
        vm.prank(address(reverter));
        c.deposit{value: extra}();
        // Record balance before withdrawal
        uint256 balanceBefore = address(c).balance;
        // Perform withdrawal from the reverter's address
        vm.prank(address(reverter));
        // The call will not revert (bug) but the transfer fails silently
        c.withdrawAll();
        // 3. Assert: The contract's balance must have decreased by (amount + extra) if the withdrawal succeeded non-revertingly.
        // Under the bug, the transfer fails, balance is not decreased, so the invariant breaks.
        assertEq(address(c).balance, balanceBefore - (uint256(amount) + uint256(extra)), "balance must decrease by total withdrawn credit");
    }
}

