pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, uint96 creditAmount, address reverter) public {
        // Bound amounts to avoid overflow and keep wide domain
        amount = uint96(bound(amount, 1, type(uint96).max));
        creditAmount = uint96(bound(creditAmount, 1, type(uint96).max));
        vm.assume(reverter != address(this));

        // Deploy a minimal adversarial callee that always reverts on receiving ETH
        RevertingCallee callee = new RevertingCallee();

        // Deal ETH and deposit into C to set up credits
        vm.deal(address(this), amount + creditAmount);
        c.deposit{value: amount}();
        vm.deal(address(callee), 0);
        vm.prank(address(callee));
        c.deposit{value: creditAmount}();

        uint balanceBefore = address(c).balance;
        uint creditBefore = c.credit(address(callee));

        // callee calls withdrawAll; the transfer will revert inside the low-level call
        vm.prank(address(callee));
        try c.withdrawAll() { } catch { }

        uint balanceAfter = address(c).balance;
        uint creditAfter = c.credit(address(callee));

        // General invariant: contract balance + total outstanding credits should equal total deposits.
        // Since only two deposits were made (this and callee), total deposits = amount + creditAmount.
        // After withdrawAll, if credit is zero, the corresponding ETH must have been transferred out.
        // If credit is non-zero (transfer failed), balance must not have decreased.
        // Simplified: balance must equal total deposits minus successfully withdrawn amounts.
        // Since callee's credit was zeroed but transfer failed, balance decreased incorrectly.
        // Assert: if creditAfter == 0, then balanceAfter + creditAfter == balanceBefore - creditBefore + creditAfter (i.e., balance decreased by creditBefore).
        // But the buggy version deducts balance without sending ETH, breaking this.
        assertTrue(creditAfter == 0 ? balanceAfter == balanceBefore - creditBefore : balanceAfter == balanceBefore);
    }
}

contract RevertingCallee {
    fallback() external payable { revert(); }
}

