pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool useReverter) public {
        // Bind to avoid overflow, keep domain wide
        amount = bound(amount, 1, 1000 ether);

        // Deploy adversarial helper that reverts on ETH reception
        Reverter reverter = new Reverter();
        address depositor = makeAddr("depositor");
        address withdrawer = useReverter ? address(reverter) : makeAddr("normal_withdrawer");

        // Setup: fund depositor and deposit
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Fund withdrawer with gas but no extra ETH
        vm.deal(withdrawer, 1 ether);
        // The withdrawer calls withdrawAll (prank sets msg.sender)
        vm.prank(withdrawer);
        c.withdrawAll();

        // After withdrawAll, sum of all credits must not exceed contract balance
        // We check balance >= sum of credits of depositor and withdrawer
        uint256 balance = address(c).balance;
        uint256 creditDep = c.credit(depositor);
        uint256 creditWith = c.credit(withdrawer);
        assertTrue(balance >= creditDep + creditWith);
    }
}

