        vm.assume(depositAmount > 0);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        RevertingReceiver r = new RevertingReceiver();
        vm.deal(address(r), 0);
        uint256 creditBefore = c.creditView(depositor);
        require(creditBefore == depositAmount, "deposit failed");

        // Use the reverting receiver as the caller, so its receive() reverts
        vm.prank(address(r));
        try c.withdrawAll() { } catch { }

        // After withdrawAll attempt, balance should equal total remaining credits (only depositor has credit)
        // The bug breaks this: balance was deducted but credit was zeroed, and ETH wasn't sent, so balance < creditView(depositor)
        uint256 remainingCredit = c.creditView(depositor);
        uint256 contractBalance = address(c).balance;
        assertTrue(contractBalance >= remainingCredit);
    }
}

contract RevertingReceiver {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
    function creditView(address a) external view returns (uint256) {
        return C(msg.sender).creditView(a);
    }
}

