pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        // Keep the domain wide: only bound total deposit to avoid overflow on tracking sum
        vm.assume(depositAmount < type(uint256).max / 2);
        vm.assume(withdrawAmount < type(uint256).max / 2);

        // Fund actor and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 totalDeposited = depositAmount;

        // Simulate partial withdrawal by first creating credit that will be withdrawn
        // The withdrawAll function withdraws the full credit of the sender. We need to ensure
        // credit == withdrawAmount before calling withdrawAll. Since credit is only increased
        // via deposit, we must have already deposited exactly withdrawAmount (or more) from actor.
        // If withdrawAmount > depositAmount, the withdrawal amount is not fully credited;
        // we simply prune this case with vm.assume to keep the property valid.
        vm.assume(withdrawAmount <= depositAmount);

        // Adjust credit to the desired withdraw amount by resetting the credit and re-depositing.
        // We cannot directly manipulate private mappings; instead, we allow the fuzzer to decide
        // the deposit amount and then have the actor call withdrawAll only when credit matches
        // withdrawAmount. Since depositAmount >= withdrawAmount, credit is at least withdrawAmount.
        // However, credit might be larger than withdrawAmount; that's fine – withdrawAll will transfer
        // out the entire credit, and we track totalDeposited accordingly. The invariant holds regardless.
        // We simply need withdrawAmount to be the credit before the call, which is depositAmount.
        uint256 creditBefore = depositAmount; // because deposit was the only action

        vm.prank(actor);
        c.withdrawAll();

        // After withdrawal, the credit of actor is 0 (public credit mapping has auto getter)
        uint256 creditAfter = c.credit(actor);
        assertEq(creditAfter, 0, "credit should be zero after withdrawAll");

        // Invariant: totalDeposited == address(c).balance + sum of all credits
        // Only actor had credit; now credit is 0.
        // For any other address, credit is 0.
        // So address(c).balance should equal totalDeposited.
        // Bug: balance is increased instead of decreased, so address(c).balance will be
        // totalDeposited + creditBefore instead of totalDeposited - creditBefore.
        assertEq(address(c).balance, totalDeposited - creditBefore, "balance invariant broken");
    }
}

